using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notepad = new Notepad();
var webSearch = new WebSearchService();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(webSearch.SearchWeb),
    AIFunctionFactory.Create(notepad.AddNote),
    AIFunctionFactory.Create(notepad.GetNotes),
};

// ---------------------------------------------------------------------------
// Build the chat client with automatic tool invocation
// ---------------------------------------------------------------------------
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

// ---------------------------------------------------------------------------
// System prompt
// ---------------------------------------------------------------------------
var systemPrompt = """
    You are a research agent. When the user gives you a topic:
    1. Use the SearchWeb tool to find relevant information (make multiple searches with different queries to get broad coverage).
    2. Use the AddNote tool to save key findings as you go.
    3. After gathering enough information, use GetNotes to review everything you collected.
    4. Present a well-structured summary of your research to the user.
    Be thorough but concise. Cite sources where possible.
    """;

// ---------------------------------------------------------------------------
// Conversation loop
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║       🔍  Research Agent  (AI)           ║");
Console.WriteLine("║  Enter a topic to research, or 'quit'.  ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

var history = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt)
};

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("You> ");
    Console.ResetColor();

    var input = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(input))
        continue;
    if (input.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    history.Add(new ChatMessage(ChatRole.User, input));

    Console.ForegroundColor = ConsoleColor.Yellow;
    Console.Write("\nAgent> ");
    Console.ResetColor();

    // Stream the response so the user sees incremental output
    await foreach (var update in client.GetStreamingResponseAsync(history, chatOptions))
    {
        Console.Write(update.Text);
    }

    // Capture the full assistant reply into history
    var assistantReply = string.Join("", history
        .Where(m => m.Role == ChatRole.Assistant)
        .SelectMany(m => m.Contents.OfType<TextContent>())
        .Select(t => t.Text));

    // Trim history to keep context manageable (keep system + last 20 messages)
    if (history.Count > 22)
        history.RemoveRange(1, history.Count - 21);

    Console.WriteLine("\n");
}

Console.WriteLine("Goodbye!");

