/// <summary>Provides web search via the DuckDuckGo Instant Answer API.</summary>
sealed class WebSearchService
{
    private readonly HttpClient _http = new()
    {
        DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } }
    };

    [Description("Search the web for information on a query. Returns a list of result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkGray;
        Console.WriteLine($"\n  [tool] Searching web for: \"{query}\"");
        Console.ResetColor();

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var doc = await _http.GetFromJsonAsync<JsonElement>(url);

            var results = new List<string>();

            // Abstract (main answer)
            var abstractText = doc.GetProperty("Abstract").GetString();
            var abstractSource = doc.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                results.Add($"[{abstractSource}] {abstractText}");

            // Related topics
            if (doc.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(8))
                {
                    if (topic.TryGetProperty("Text", out var text))
                    {
                        var snippet = text.GetString();
                        if (!string.IsNullOrWhiteSpace(snippet))
                        {
                            var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : "";
                            results.Add($"- {snippet} ({firstUrl})");
                        }
                    }
                }
            }

            if (results.Count == 0)
                return $"No results found for \"{query}\". Try rephrasing the query.";

            return string.Join("\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }
}

/// <summary>Simple in-memory notepad for the agent to record findings.</summary>
sealed class Notepad
{
    private readonly List<string> _notes = [];

    [Description("Save a research note. Use this to record key findings while researching.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.ForegroundColor = ConsoleColor.DarkGray;
        Console.WriteLine($"\n  [tool] Note #{_notes.Count} saved ({note.Length} chars)");
        Console.ResetColor();
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        Console.ForegroundColor = ConsoleColor.DarkGray;
        Console.WriteLine($"\n  [tool] Retrieving {_notes.Count} note(s)");
        Console.ResetColor();

        return string.Join("\n\n", _notes.Select((n, i) => $"Note #{i + 1}:\n{n}"));
    }
}

